<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { supabase } from '../lib/supabase'
import { auth } from '../stores/auth'
import type { Plan } from '../lib/types'
const plans = ref<Plan[]>([]); const chosen = ref<Plan | null>(null); const loading = ref(true); const error = ref(''); const router = useRouter(); const route = useRoute(); const confirming = ref(false); const characterCount = ref(0)
const isWelcome = computed(() => route.query.welcome === '1')
function price(cents: number) { return cents === 0 ? 'Free' : `$${cents / 100}` }
async function load() { const [{ data, error: planError }, { count }] = await Promise.all([supabase.from('plans').select('*').order('sort_order'), supabase.from('characters').select('id', { count: 'exact', head: true })]); if (planError) error.value = 'Plans could not be loaded.'; plans.value = data || []; characterCount.value = count || 0; loading.value = false }
async function changePlan() { if (!chosen.value) return; confirming.value = true; const { error: changeError } = await supabase.rpc('change_plan', { new_plan_id: chosen.value.id }); confirming.value = false; if (changeError) { error.value = changeError.message.includes(':') ? changeError.message.split(':').slice(1).join(':').trim() : 'That plan change could not be completed.'; return } auth.plan = chosen.value; chosen.value = null; if (isWelcome.value) await router.push('/characters') }
function warning(plan: Plan) { return characterCount.value > plan.character_limit ? `You have ${characterCount.value} characters, which is over this plan's limit of ${plan.character_limit}. You'll keep them all, but you can't create new ones until you're under the limit.` : '' }
onMounted(() => { void load() })
</script>
<template><section class="page"><div class="center-heading"><div class="eyebrow">Choose your chapter</div><h2>Plans for every kind of story</h2><p class="muted">Start free, then make room for the legends still waiting to be written.</p></div><p v-if="error" class="form-error">{{ error }}</p><div v-if="loading" class="empty"><p class="muted">Loading plans…</p></div><div v-else class="plans-grid"><article v-for="plan in plans" :key="plan.id" class="plan-card" :class="{ featured: plan.id === 'adventurer' }"><span v-if="plan.id === 'adventurer'" class="ribbon">Popular</span><div class="plan-glyph">✦</div><div class="eyebrow">{{ plan.name }}</div><h3>{{ price(plan.price_cents) }} <small v-if="plan.price_cents">/ month</small></h3><p class="muted">Make room for your next chapter.</p><div class="plan-limit"><strong>{{ plan.character_limit }}</strong><span>character slots</span></div><button v-if="auth.plan?.id === plan.id" class="outline full" disabled>Current plan</button><button v-else class="primary full" @click="chosen = plan">Choose {{ plan.name }}</button></article></div><div v-if="chosen" class="modal-backdrop" @click.self="chosen = null"><div class="modal"><button class="modal-close" @click="chosen = null">×</button><div class="plan-glyph">✦</div><div class="eyebrow">Confirm your next chapter</div><h2>Switch to {{ chosen.name }}?</h2><p>{{ price(chosen.price_cents) }}<span v-if="chosen.price_cents">/month</span> · {{ chosen.character_limit }} characters.</p><p class="muted">This is a simulated plan change; no payment is collected.</p><p v-if="warning(chosen)" class="warning">{{ warning(chosen) }}</p><button class="primary full" :disabled="confirming" @click="changePlan">{{ confirming ? 'Changing plan…' : 'Confirm plan change' }}</button></div></div></section></template>
